const body = $('Webhook').first().json.body;
const SKALA = 1; // ubah ke 1000 kalau semua harga terlihat dalam ribuan
const model = String(body.model).toLowerCase();
const storage = String(body.storage_gb);

const kunci = model.split(/\s+/).filter(t => /\d/.test(t));
const varian = ['pro', 'max', 'plus', 'ultra', 'mini', 'lite', 'fe', 'neo', 'turbo', 'se'];
const varianDilarang = varian.filter(v => !new RegExp('\\b' + v + '\\b').test(model));
const buang = ['dicari', 'wtb', 'case', 'casing', 'tempered', 'charger', 'lcd', 'sparepart', 'dus', 'kardus', 'minus', 'mati total'];

const rows = $input.all().map(i => i.json)
  .filter(it => it.marketplace_listing_title || it.custom_title)
  .map(it => ({
    judul: String(it.marketplace_listing_title || it.custom_title || '').toLowerCase(),
    harga: Number(String(it.listing_price?.amount ?? '').replace(/[^\d]/g, '')) * SKALA,
    dijual: !(it.is_sold || it.is_pending),
  }));

if (!rows.length) {
  throw new Error('Apify tidak mengembalikan iklan untuk pencarian ini.');
}

const storageDiJudul = j => [...j.matchAll(/\b(64|128|256|512)\s*(?:gb|g)?\b/g)].map(m => m[1]);

const valid = rows.filter(r => {
  if (!r.dijual || r.harga < 500000) return false;
  if (!kunci.every(k => r.judul.includes(k))) return false;
  if (buang.some(b => r.judul.includes(b))) return false;
  if (varianDilarang.some(v => new RegExp('\\b' + v + '\\b').test(r.judul))) return false;
  const st = storageDiJudul(r.judul);
  if (st.length && !st.includes(storage)) return false;
  return true;
});

if (!valid.length) {
  throw new Error('Tidak ada iklan valid dari ' + rows.length + ' iklan. Contoh: ' + JSON.stringify(rows.slice(0, 5)));
}

const urut = valid.map(r => r.harga).sort((a, b) => a - b);
const med = a => a[Math.floor(a.length / 2)];
const m = med(urut);
const akhir = urut.filter(p => p >= m * 0.6 && p <= m * 1.6);

return [{ json: {
  harga_pasaran: med(akhir),
  jumlah_iklan: akhir.length,
  debug: { iklan_awal: rows.length, lolos_filter: valid.length, min: akhir[0], maks: akhir[akhir.length - 1] }
} }];
